#define FG_CONV_L20_NO_MAIN
#include "macos_probe.mm"
#include "custom_conv2_contract.h"
namespace{namespace c=fg_custom_conv2;struct Params{std::uint32_t residual;};
std::vector<std::uint8_t>Read2(const std::filesystem::path&p){std::ifstream s(p,std::ios::binary|std::ios::ate);if(!s)throw std::runtime_error("read");auto n=s.tellg();std::vector<std::uint8_t>b(static_cast<std::size_t>(n));s.seekg(0);s.read(reinterpret_cast<char*>(b.data()),n);return b;}
void Receipt(const std::filesystem::path&p,const c::Layer&l,const std::string&id,std::uint8_t poison,const std::vector<std::uint8_t>&w0,const std::vector<std::uint8_t>&b0,const std::vector<std::uint8_t>&a0,const std::vector<std::uint8_t>&r0,const std::vector<std::uint8_t>&w1,const std::vector<std::uint8_t>&b1,const std::vector<std::uint8_t>&a1,const std::vector<std::uint8_t>&r1,const std::vector<std::uint8_t>&out,std::size_t mismatch,std::size_t canary,std::size_t collisions,const std::string&device){std::ofstream s(p);bool pass=mismatch==0&&canary==0;s<<"{\n  \"schema\": \"neuralstudio.fg.custom-conv2-run.v1\",\n  \"backend\": \"mac-metal\",\n  \"layer_id\": \""<<l.id<<"\",\n  \"run_id\": \""<<id<<"\",\n  \"process_id\": "<<getpid()<<",\n  \"poison_byte\": "<<unsigned(poison)<<",\n  \"trace_launch_token\": \"launch-"<<std::setw(6)<<std::setfill('0')<<l.launch<<"\",\n"<<std::setfill(' ')<<"  \"module_token\": 57,\n  \"module_bytes\": "<<c::kModuleBytes<<",\n  \"module_sha256\": \""<<c::kModuleSha256<<"\",\n  \"metal_function\": \"fg_custom_block0_conv2\",\n  \"selected_rtx_grid\": [10, 23, 1],\n  \"selected_rtx_block\": [32, 1, 8],\n  \"metal_dispatch_threads\": [80, 46, 64],\n  \"metal_threads_per_threadgroup\": [8, 4, 1],\n  \"packed_parameter_bytes\": 92,\n  \"abi_scalars\": [64, 3, 3, 64, 1, 46, 80, 64, 1, 46, 80, 64, "<<(l.residual?1:0)<<"],\n  \"input_shape_nhwc\": [1, 46, 80, 64],\n  \"output_shape_nhwc\": [1, 46, 80, 64],\n  \"fused_operations\": [\"conv3x3\", \"leaky_relu\", \"clamp_-6_6\", \"optional_residual_add\"],\n  \"residual_enabled\": "<<(l.residual?"true":"false")<<",\n  \"weight_source_token\": "<<l.weight_token<<",\n  \"bias_source_token\": "<<l.bias_token<<",\n  \"model_capture_manifest_sha256\": \""<<c::kManifestSha256<<"\",\n  \"weight_pre_sha256\": \""<<Sha256(w0)<<"\",\n  \"weight_post_sha256\": \""<<Sha256(w1)<<"\",\n  \"bias_pre_sha256\": \""<<Sha256(b0)<<"\",\n  \"bias_post_sha256\": \""<<Sha256(b1)<<"\",\n  \"input_generator\": \"splitmix64-fg-custom-conv2-v1\",\n  \"input_pre_sha256\": \""<<Sha256(a0)<<"\",\n  \"input_post_sha256\": \""<<Sha256(a1)<<"\",\n  \"residual_pre_sha256\": \""<<Sha256(r0)<<"\",\n  \"residual_post_sha256\": \""<<Sha256(r1)<<"\",\n  \"output_sha256\": \""<<Sha256(out)<<"\",\n  \"output_bytes\": "<<out.size()<<",\n  \"input_mismatched_bytes\": "<<mismatch<<",\n  \"canary_mismatched_bytes\": "<<canary<<",\n  \"per_run_poison_collision_halfwords\": "<<collisions<<",\n  \"per_run_write_coverage_conclusive\": false,\n  \"external_model_files_opened\": true,\n  \"expected_output_file_opened\": false,\n  \"device_name\": \""<<device<<"\",\n  \"address_fields_recorded\": false,\n  \"result\": \""<<(pass?"pass":"fail")<<"\"\n}\n";}}
int main(int argc,const char*argv[]){@autoreleasepool{if(argc!=8){std::cerr<<"usage=fg-custom-conv2-mac <layer> <metallib> <weights> <bias> <out> <run> <poison>\n";return 2;}try{const auto&l=c::Find(argv[1]);auto w0=Read2(argv[3]),b0=Read2(argv[4]);if(w0.size()!=c::kWeightBytes||Sha256(w0)!=l.weight_sha256||b0.size()!=c::kBiasBytes||Sha256(b0)!=l.bias_sha256)throw std::runtime_error("identity");char*e=nullptr;auto pv=std::strtoul(argv[7],&e,16);if(e==argv[7]||*e!='\0'||pv>255)throw std::runtime_error("poison");auto poison=std::uint8_t(pv);std::filesystem::path outdir=argv[5];std::filesystem::create_directories(outdir);auto a0=c::Input(l,false),r0=c::Input(l,true);id<MTLDevice>d=MTLCreateSystemDefaultDevice();NSError*error=nil;id<MTLLibrary>lib=[d newLibraryWithURL:[NSURL fileURLWithPath:[NSString stringWithUTF8String:argv[2]]] error:&error];id<MTLFunction>fn=[lib newFunctionWithName:@"fg_custom_block0_conv2"];id<MTLComputePipelineState>pipe=[d newComputePipelineStateWithFunction:fn error:&error];if(!pipe)throw std::runtime_error("pipeline");id<MTLBuffer>w=Guarded(d,&w0,c::kWeightBytes,0),b=Guarded(d,&b0,c::kBiasBytes,0),a=Guarded(d,&a0,c::kTensorBytes,0),r=Guarded(d,&r0,c::kTensorBytes,0),o=Guarded(d,nullptr,c::kTensorBytes,poison);Params params{l.residual?1u:0u};id<MTLCommandBuffer>cmd=[[d newCommandQueue]commandBuffer];id<MTLComputeCommandEncoder>enc=[cmd computeCommandEncoder];[enc setComputePipelineState:pipe];[enc setBuffer:w offset:kGuardBytes atIndex:0];[enc setBuffer:b offset:kGuardBytes atIndex:1];[enc setBuffer:a offset:kGuardBytes atIndex:2];[enc setBuffer:r offset:kGuardBytes atIndex:3];[enc setBuffer:o offset:kGuardBytes atIndex:4];[enc setBytes:&params length:sizeof(params) atIndex:5];[enc dispatchThreads:MTLSizeMake(80,46,64) threadsPerThreadgroup:MTLSizeMake(8,4,1)];[enc endEncoding];[cmd commit];[cmd waitUntilCompleted];if(cmd.status!=MTLCommandBufferStatusCompleted)throw std::runtime_error("command");auto w1=Payload(w,c::kWeightBytes),b1=Payload(b,c::kBiasBytes),a1=Payload(a,c::kTensorBytes),r1=Payload(r,c::kTensorBytes),out=Payload(o,c::kTensorBytes);auto mismatch=Mismatches(w0,w1)+Mismatches(b0,b1)+Mismatches(a0,a1)+Mismatches(r0,r1);auto canary=CanaryMismatches(w,c::kWeightBytes)+CanaryMismatches(b,c::kBiasBytes)+CanaryMismatches(a,c::kTensorBytes)+CanaryMismatches(r,c::kTensorBytes)+CanaryMismatches(o,c::kTensorBytes);Receipt(outdir/"run-receipt.json",l,argv[6],poison,w0,b0,a0,r0,w1,b1,a1,r1,out,mismatch,canary,UntouchedHalfwords(out,poison),d.name.UTF8String);Write(outdir/"output.bin",out);Write(outdir/"input-after.bin",a1);bool pass=mismatch==0&&canary==0;std::cout<<"probe=fg_custom_conv2_mac\nlayer="<<l.id<<"\noutput_sha256="<<Sha256(out)<<"\nresult="<<(pass?"pass":"fail")<<'\n';return pass?0:3;}catch(const std::exception&x){std::cerr<<"error="<<x.what()<<'\n';return 1;}}}
